<!DOCTYPE html><html lang="id"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#17231d;font-size:11px}h1{font-size:24px;margin-bottom:4px}.muted{color:#68766f}.meta{width:100%;margin:24px 0}.meta td{padding:5px 0}table.items{width:100%;border-collapse:collapse}.items th,.items td{padding:9px;border-bottom:1px solid #dce3de;text-align:left}.items th{background:#edf4ef}.total{text-align:right;font-size:16px;font-weight:bold;margin-top:20px}</style></head><body><h1>Invoice {{ $invoice->invoice_no ?: '#'.$invoice->id }}</h1><div class="muted">{{ config('app.name') }} · {{ $invoice->created_at->format('d M Y') }}</div><table class="meta"><tr><td>Pelanggan</td><td>{{ $invoice->contact?->name }}</td></tr><tr><td>Status pembayaran</td><td>{{ $invoice->payment_status }}</td></tr></table><table class="items"><thead><tr><th>Produk</th><th>Qty</th><th>Harga</th><th>Subtotal</th></tr></thead><tbody>@foreach($invoice->lines as $line)<tr><td>{{ $line->variant?->product?->name ?? 'Produk' }}</td><td>{{ number_format($line->quantity,3,',','.') }}</td><td>Rp {{ number_format($line->unit_price,0,',','.') }}</td><td>Rp {{ number_format(($line->quantity*$line->unit_price)-$line->discount,0,',','.') }}</td></tr>@endforeach</tbody></table><div class="total">Total: Rp {{ number_format($invoice->total,0,',','.') }}</div></body></html>
